    }

    const float sp = (max_val > 20.0f) ? max_val : log1pf(expf(max_val));
    output[(n * C + c) * H_out * W_out + h_out * W_out + w_out] = max_val * tanhf(sp);
}

// Specialized kernel for pool_size=2, pool_stride=2 using float2 vectorized row loads
__global__ void fused_sub_hardswish_maxpool2x2_mish_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    const int N, const int C, const int H, const int W,
    const int H_out, const int W_out,
    const float subtract_val
) {
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    const int total = N * C * H_out * W_out;
    if (idx >= total) return;

    const int w_out = idx % W_out;
    const int h_out = (idx / W_out) % H_out;
    const int c     = (idx / (W_out * H_out)) % C;
    const int n     = idx / (W_out * H_out * C);

    const int h0 = h_out * 2;
    const int w0 = w_out * 2;
    const int nc_off = (n * C + c) * H * W;

    // Check if we can use float2 loads (both columns in-bounds and 8-byte aligned)
    // w0 is always even (w_out*2), and W is the original spatial width.
    // float2 load requires: base pointer + nc_off + h_row*W + w0 is 8-byte aligned.
    // Since the tensor is allocated by PyTorch (typically 256-byte aligned) and
    // nc_off*4 bytes offset, alignment depends on nc_off and W parity.
    // We use vectorized path only when w0+1 < W (both columns in bounds).
    // For alignment: index nc_off + h*W + w0 must be even (since float2 = 2 floats).
    // nc_off + h*W is fixed per (n,c,h); w0 = 2*w_out is always even, so
    // (nc_off + h*W + w0) has same parity as (nc_off + h*W).
    // We check 8-byte alignment via pointer arithmetic below.

    float max_val = -FLT_MAX;

    // Row 0
    if (h0 < H) {
        const int base0 = nc_off + h0 * W + w0;
        if (w0 + 1 < W) {
            // Check 8-byte (float2) alignment
            const float* ptr0 = input + base0;
            if (((uintptr_t)ptr0 & 7) == 0) {
                float2 v2 = *reinterpret_cast<const float2*>(ptr0);
                float a = v2.x - subtract_val;
                float b = v2.y - subtract_val;
                a = a * fminf(fmaxf(a + 3.0f, 0.0f), 6.0f) * (1.0f / 6.0f);
                b = b * fminf(fmaxf(b + 3.0f, 0.0f), 6.0f) * (1.0f / 6.0f);
                max_val = fmaxf(a, b);
            } else {
                float a = __ldg(input + base0) - subtract_val;
                float b = __ldg(input + base0 + 1) - subtract_val;
                a = a * fminf(fmaxf(a + 3.0f, 0.0f), 6.0f) * (1.0f / 6.0f);
                b = b * fminf(fmaxf(b + 3.0f, 0.0f), 6.0f) * (1.0f / 6.0f);
                max_val = fmaxf(a, b);
            }
        } else if (w0 < W) {
            float a = __ldg(input + base0) - subtract_val;
            a = a * fminf(fmaxf(a + 3.0f, 0.0f), 6.0f) * (1.0f / 6.0f);
            max_val = a;
        }
    }

    // Row 1
    if (h0 + 1 < H) {
        const int base1 = nc_off + (h0 + 1) * W + w0;
        if (w0 + 1 < W) {
            const float* ptr1 = input + base1;
            if (((uintptr_t)ptr1 & 7) == 0) {
                float2 v2 = *reinterpret_cast<const float2*>(ptr1);
                float a = v2.x - subtract_val;
                float b = v2.y - subtract_val;
                a = a * fminf(fmaxf(a + 3.0f, 0.0f), 6.0f) * (1.0f / 6.0f);
                b = b * fminf(fmaxf(b + 3.0f, 0.0f), 6.0f) * (1.0f / 6.0f);
                max_val = fmaxf(max_val, fmaxf(a, b));
            } else {
                float a = __ldg(input + base1) - subtract_val;
                float b = __ldg(input + base1 + 1) - subtract_val;
                a = a * fminf(fmaxf(a + 3.0f, 0.0f), 6.0f) * (1.0f / 6.0f);
                b = b * fminf(fmaxf(b + 3.0f, 0.0f), 6.0f) * (1.0f / 6.0f);
                max_val = fmaxf(max_val, fmaxf(a, b));
            }
        } else if (w0 < W) {
            float a = __ldg(input + base1) - subtract_val;
            a = a * fminf(fmaxf(a + 3.0f, 0.0f), 6.0f) * (1.0f / 6.0f);
            max_val = fmaxf(max_val, a);
        }
    }

    const float sp = (max_val > 20.0f) ? max_val : log1pf(expf(max_val));
    output[(n * C + c) * H_out * W_out + h_out * W_out + w_out] = max_val * tanhf(sp);
}

