    const int c     = (idx / (W_out * H_out)) % C;
    const int n     = idx / (W_out * H_out * C);

    const int h0 = h_out * 2;
    const int w0 = w_out * 2;
    const int nc_off = (n * C + c) * H * W;

    float max_val = -FLT_MAX;

    // Unrolled 2x2 scalar loads: (h0,w0), (h0,w0+1), (h0+1,w0), (h0+1,w0+1)
    if (h0 < H && w0 < W) {
        float v = __ldg(&input[nc_off + h0 * W + w0]);
        v -= subtract_val;
        v = v * fminf(fmaxf(v + 3.0f, 0.0f), 6.0f) * (1.0f / 6.0f);
        max_val = fmaxf(max_val, v);
    }
    if (h0 < H && w0 + 1 < W) {
